"use strict";

window.addEventListener("DOMContentLoaded", () => {
  console.log("🌍 The P2V initializing...");

  const map = L.map("map").setView([28.6139, 77.209], 5);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "&copy; OpenStreetMap contributors"
  }).addTo(map);

  const icons = {
    "Priority": L.icon({ iconUrl: "icons/red-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
    "Tier I": L.icon({ iconUrl: "icons/orange-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
    "Tier II": L.icon({ iconUrl: "icons/yellow-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
    "Tier III": L.icon({ iconUrl: "icons/green-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
    "Tier IV": L.icon({ iconUrl: "icons/blue-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
    "Tier V": L.icon({ iconUrl: "icons/purple-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
    default: L.icon({ iconUrl: "icons/gray-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] })
  };

  const tableBody = document.querySelector("#places-table tbody");
  const locateBtn = document.getElementById("locate-me");
  const filterToggle = document.getElementById("filter-toggle");
  const filterBar = document.getElementById("filter-bar");
  const filterOverlay = document.getElementById("filter-overlay");

  let allPlaces = [];
  let markers = [];
  let userLat, userLon, userMarker = null;
  let userStatus = JSON.parse(localStorage.getItem("userStatus")) || {};
  let watchId = null;
  let autoFollow = false;
  // Deep-link intent (filled from URL on initial load)
  let pendingDeepLink = null;

  let deepLinkHandled = false; // to mark once we’ve opened it

  // ===== P2V state manager (replace window.__P2V_skipAutoFollow usage) =====
  const P2VState = (function() {
    let _skip = false;
    let _timer = null;

    function _debugLog(action, ms) {
      // Lightweight log — comment out or remove in production
      console.log(`[P2VState] ${action}` + (ms ? ` for ${ms}ms` : ''));
    }

    return {
      // set skip for ms milliseconds (default 2000). If already set, it resets the timer.
      setSkipAutoFollow: function(ms = 2000) {
        _skip = true;
        if (_timer) clearTimeout(_timer);
        _timer = setTimeout(() => {
          _skip = false;
          _timer = null;
          _debugLog('auto-follow skip cleared (timeout)');
        }, ms);
        _debugLog('auto-follow skip set', ms);
      },
      // clear immediately
      clearSkipAutoFollow: function() {
        _skip = false;
        if (_timer) { clearTimeout(_timer); _timer = null; }
        _debugLog('auto-follow skip cleared (manual)');
      },
      // boolean check
      isSkipAutoFollow: function() {
        return !!_skip;
      }
    };
  })();






  // Parse URL for deep-link parameters and store intent
  (function checkDeepLinkFromUrl() {
    try {
      const params = new URLSearchParams(location.search);
      const lat = params.get("lat");
      const lon = params.get("lon");
      const place = params.get("place");

      if (lat && lon) {
        pendingDeepLink = {
          type: "coords",
          lat: parseFloat(lat),
          lon: parseFloat(lon),
          placeSlug: place || null
        };
        // tell locateUser to avoid recentering until we process the deep link
        P2VState.setSkipAutoFollow(2500);
        console.log("Deep-link detected (coords):", pendingDeepLink);
      } else if (place) {
        pendingDeepLink = { type: "slug", placeSlug: place };
        // tell locateUser to avoid recentering until we process the deep link
        P2VState.setSkipAutoFollow(2500);
        console.log("Deep-link detected (slug):", pendingDeepLink);
      }


    } catch (err) {
      console.warn("Deep-link parse error:", err);
    }
  })();



  // ======= Helper functions (move to top-level) =======
  function escapeHtml(str) {
    if (!str) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }
  function escapeHtmlAttr(str) {
    if (!str) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;")
      .replace(/</g, "&lt;");
  }

  // Replace existing window.sharePlace with this clean version
  window.sharePlace = async function (url, name) {
    // Ensure url is the full place URL (already encoded when placed on button dataset)
    const safeName = name || "The P2V";
    const shareText = `${safeName} — Found on The P2V\n${url}`;

    try {
      // Native share (mobile first)
      if (navigator.share) {
        await navigator.share({
          title: `${safeName} — The P2V`,
          text: shareText,
          url: url
        });
        try { gtag && gtag('event', 'place_shared', { event_category: 'engagement', event_label: safeName }); } catch(e) {}
        return;
      }

      // Fallback: copy to clipboard
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(shareText);
        try { gtag && gtag('event', 'place_link_copied', { event_category: 'engagement', event_label: safeName }); } catch(e) {}
        alert("Link copied to clipboard — paste in WhatsApp/Telegram to share!");
        return;
      }

      // Last fallback: show prompt with the single link
      window.prompt("Copy this link to share:", url);

    } catch (err) {
      console.error("sharePlace error:", err);
      // final fallback: show the single URL (not duplicated)
      alert("Couldn't share automatically — copy this link:\n" + url);
    }
  };

  // ======= end helpers =======


  // 🧭 Helper: Engagement score tracking
  function updateEngagementScore(points) {
    gtag("event", "engagement_score_update", {
      event_category: "score",
      value: points
    });
  }

  
  // 🧩 GA4: Returning vs First-time user tracking
  if (localStorage.getItem("visited_before")) {
    gtag("event", "returning_user", { event_category: "user" });
  } else {
    gtag("event", "first_time_user", { event_category: "user" });
    localStorage.setItem("visited_before", true);
  }



  // 🧭 Distance
  function getDistance(e, t, a, o) {
    const R = 6371,
      dLat = (a - e) * Math.PI / 180,
      dLon = (o - t) * Math.PI / 180;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(e * Math.PI / 180) * Math.cos(a * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
  }

  // 📍 Live location tracking — improved to avoid re-render loops
  function locateUser() {
    if (!navigator.geolocation) {
      alert("❌ Geolocation not supported.");
      return;
    }

    if (watchId) navigator.geolocation.clearWatch(watchId);

    let firstPositionObtained = false;

    watchId = navigator.geolocation.watchPosition(
      pos => {
        userLat = pos.coords.latitude;
        userLon = pos.coords.longitude;

        // Add or update user marker
        if (!userMarker) {
          userMarker = L.marker([userLat, userLon]).addTo(map).bindPopup("📍 You are here");
        } else {
          userMarker.setLatLng([userLat, userLon]);
        }

        // On the very first position, run full render (applyFilters).
        // Subsequent updates only recenter if allowed.
        if (!firstPositionObtained) {
          firstPositionObtained = true;
          try {
            console.log("locateUser: first position obtained — running applyFilters()");
            applyFilters();
          } catch (err) {
            console.warn("locateUser applyFilters error:", err);
          }
          return;
        }

        // Subsequent updates: only recenter map if autoFollow is on and no deep link active.
        if (autoFollow && !P2VState.isSkipAutoFollow() && !deepLinkHandled) {
          const currentZoom = map.getZoom();
          map.flyTo([userLat, userLon], currentZoom, { animate: true, duration: 0.8 });
        }
        // DO NOT call applyFilters() again here (avoids re-creating markers repeatedly).
      },
      err => {
        console.warn("GPS error:", err.message);
        // still run applyFilters() once if not yet done to render markers
        try {
          if (!firstPositionObtained) { firstPositionObtained = true; applyFilters(); }
        } catch (e) { console.warn("locateUser fallback applyFilters error", e); }
      },
      { enableHighAccuracy: true, maximumAge: 10000, timeout: 20000 }
    );
  }

  // 🎨 Row colors
  function applyRowColor(status, row) {
    const colors = {
      "Visited": "#d6f5d6",
      "Not Interested": "#f2f2f2",
      "Spare/Skip": "#fff5cc",
      "Want to Visit": "#ffffff",
      "Visiting Later": "#d9f9f9"
    };
    if (row && row.style) row.style.backgroundColor = colors[status] || "#fff";
  }

  // ♻️ Restore filters
  function restoreFilters() {
    try {
      const saved = JSON.parse(localStorage.getItem("userFilters"));
      if (!saved) return;
      document.querySelectorAll(".pop-check").forEach(cb => cb.checked = saved.popularity.includes(cb.value));
      document.getElementById("distanceFilter").value = saved.distance;
      document.getElementById("statusFilter").value = saved.status;
    } catch (err) { console.warn("restoreFilters error", err); }
  }

  // 🔍 Apply filters
  function applyFilters() {
    try {
      const saved = {
        popularity: Array.from(document.querySelectorAll(".pop-check:checked")).map(cb => cb.value),
        distance: document.getElementById("distanceFilter").value,
        status: document.getElementById("statusFilter").value
      };
      localStorage.setItem("userFilters", JSON.stringify(saved));

      // 🧩 GA4: Log filter combination
      gtag("event", "filter_combination", {
        event_category: "filters",
        popularity: saved.popularity.join(","),
        distance: saved.distance,
        status: saved.status
      });


      const t = saved.popularity, a = saved.distance, o = saved.status;
      tableBody.innerHTML = "";
      markers.forEach(m => map.removeLayer(m));
      markers = [];

      let list = allPlaces.filter(item => {
        const lat = parseFloat(item.Latitude);
        const lon = parseFloat(item.Longitude);
        if (isNaN(lat) || isNaN(lon)) return false;
        item.Latitude = lat;
        item.Longitude = lon;

        userLat && userLon ? item.Distance = getDistance(userLat, userLon, lat, lon) : item.Distance = null;
        let ok = t.includes(item.Popularity);
        if (a !== "All" && item.Distance && item.Distance > parseFloat(a)) ok = false;
        const st = userStatus[item.Name] || "Want to Visit";
        if (o !== "All" && st !== o) ok = false;
        return ok;
      });

      if (userLat && userLon) list.sort((x, y) => x.Distance - y.Distance);

      // Keep track of currently open popup globally for this filter update
      // Keep track of the currently open popup globally
      let currentPopup = null;


    // ---------- Safe marker + popup creation (no template literals) ----------
    list.slice(0, 200).forEach(function(item) {
      try {
        const icon = icons[item.Popularity] || icons.default;

        // Prefer canonical permalink/slug stored in Firestore
        const placeSlug = item.slug || (item.Name || '').trim().replace(/\s+/g, '-').toLowerCase();
        const placeUrl = item.permalink || (location.origin + '/?place=' + encodeURIComponent(placeSlug) + '&lat=' + item.Latitude + '&lon=' + item.Longitude);


        // Create popup DOM element instead of string template
        const popupDiv = document.createElement('div');
        popupDiv.className = 'ptv-popup';

        const titleEl = document.createElement('strong');
        titleEl.textContent = item.Name || '';
        popupDiv.appendChild(titleEl);

        popupDiv.appendChild(document.createElement('br'));

        const locText = document.createTextNode(item.CountryState || 'Unknown Location');
        popupDiv.appendChild(locText);
        popupDiv.appendChild(document.createElement('br'));

        const popText = document.createTextNode(item.Popularity || '');
        popupDiv.appendChild(popText);
        popupDiv.appendChild(document.createElement('br'));

        if (item.Distance) {
          const distText = document.createTextNode(item.Distance.toFixed(2) + ' km');
          popupDiv.appendChild(distText);
          popupDiv.appendChild(document.createElement('br'));
        }

        // buttons container
        const btnWrap = document.createElement('div');
        btnWrap.style.marginTop = '8px';
        btnWrap.style.display = 'flex';
        btnWrap.style.gap = '6px';

        // Get Directions button
        const dirBtn = document.createElement('button');
        dirBtn.className = 'dir-btn';
        dirBtn.type = 'button';
        dirBtn.dataset.lat = item.Latitude;
        dirBtn.dataset.lon = item.Longitude;
        dirBtn.dataset.name = item.Name || '';
        dirBtn.textContent = '🧭 Get Directions';
        btnWrap.appendChild(dirBtn);

        // Share button
        const shareBtn = document.createElement('button');
        shareBtn.className = 'share-btn';
        shareBtn.type = 'button';
        shareBtn.dataset.url = encodeURI(placeUrl);
        shareBtn.dataset.name = item.Name || '';
        shareBtn.textContent = '🔗 Share';
        btnWrap.appendChild(shareBtn);

        popupDiv.appendChild(btnWrap);

        // create marker and bind popup using the DOM node
        const marker = L.marker([item.Latitude, item.Longitude], { icon: icon }).addTo(map);
        marker.bindPopup(popupDiv, {
          autoClose: false,
          closeOnClick: false,
          closeButton: true,
          autoPan: false,
          className: 'custom-popup'
        });

        // attach popupopen handler to rewire listeners (safer)
        marker.on('popupopen', function(e) {
          try {
            // query buttons from the popup container (Leaflet clones content)
            const popupEl = e.popup.getElement();
            if (!popupEl) return;

            // find fresh buttons
            const freshDir = popupEl.querySelector('.dir-btn');
            const freshShare = popupEl.querySelector('.share-btn');

            if (freshDir) {
              // remove previous listeners by cloning
              const cloneDir = freshDir.cloneNode(true);
              freshDir.parentNode.replaceChild(cloneDir, freshDir);
              cloneDir.addEventListener('click', function() {
                const lat = parseFloat(this.dataset.lat);
                const lon = parseFloat(this.dataset.lon);
                const name = this.dataset.name || '';
                window.openDirections(lat, lon, name);
              });
            }

            if (freshShare) {
              const cloneShare = freshShare.cloneNode(true);
              freshShare.parentNode.replaceChild(cloneShare, freshShare);
              cloneShare.addEventListener('click', function() {
                const url = this.dataset.url;
                const name = this.dataset.name || '';
                window.sharePlace(url, name);
              });
            }
          } catch (err) {
            console.error('popupopen attach error', err);
          }
        });

        // openMarkerPopup function
        function openMarkerPopup() {
          if (currentPopup && map.hasLayer(currentPopup)) {
            map.closePopup(currentPopup);
          }
          marker.openPopup();
          currentPopup = marker.getPopup();
          setTimeout(function() {
            if (currentPopup && map.hasLayer(currentPopup)) {
              map.panTo(marker.getLatLng());
            }
          }, 300);
        }

        marker.on('click', openMarkerPopup);
        marker.on('tap', openMarkerPopup);

        markers.push(marker);

        // Table row creation (same logic)
        const row = document.createElement('tr');
        row.innerHTML = '<td>' + (item.Name || '') + '</td>' +
                        '<td>' + (item.Popularity || '') + '</td>' +
                        '<td>' + (item.Distance ? item.Distance.toFixed(2) : '-') + '</td>' +
                        '<td><select class="status-select" data-name="' + (item.Name || '') + '">' +
                          '<option value="Want to Visit">Want to Visit</option>' +
                          '<option value="Visiting Later">Visiting Later</option>' +
                          '<option value="Visited">Visited</option>' +
                          '<option value="Not Interested">Not Interested</option>' +
                          '<option value="Spare/Skip">Spare/Skip</option>' +
                        '</select></td>';

        const sel = row.querySelector('.status-select');
        sel.value = userStatus[item.Name] || 'Want to Visit';
        applyRowColor(sel.value, row);

        sel.addEventListener('change', function(ev) {
          const v = ev.target.value;
          userStatus[item.Name] = v;
          localStorage.setItem('userStatus', JSON.stringify(userStatus));
          applyRowColor(v, row);
          try {
            gtag('event', 'status_change', { event_category: 'status', event_label: item.Name, value: v });
          } catch(e){}
          updateEngagementScore(2);
        });

        row.addEventListener('click', function() {
          map.flyTo([item.Latitude, item.Longitude], 14, { animate: true });
          setTimeout(openMarkerPopup, 400);
        });

        tableBody.appendChild(row);

      } catch (err) {
        console.error('marker loop error', err);
      }
    });
    // ---------- end safe block ----------

    // debug: show how many markers were created and whether a deep-link exists
    console.log("Deep-link debug — markers:", markers.length, "pendingDeepLink:", pendingDeepLink);

     // ---------- Deep-link consumer (run once after markers are created) ----------
    if (pendingDeepLink) {
      try {
        console.log("Deep-link consumer running. pendingDeepLink:", pendingDeepLink);

        // mark handled early so locateUser won't steal the view while this runs
        deepLinkHandled = true;

        // consume early to avoid repeated attempts
        const dl = pendingDeepLink;
        pendingDeepLink = null;
        P2VState.setSkipAutoFollow(2500);

        let targetMarker = null;

        if (dl.type === "coords" && !Number.isNaN(dl.lat) && !Number.isNaN(dl.lon)) {
          targetMarker = markers.find(m => {
            const pos = m.getLatLng();
            return Math.abs(pos.lat - dl.lat) < 0.0006 && Math.abs(pos.lng - dl.lon) < 0.0006;
          });
        }

        if (!targetMarker && dl.placeSlug) {
          const slug = (dl.placeSlug || "").toString().toLowerCase();
          for (let i = 0; i < markers.length; i++) {
            const m = markers[i];
            const pos = m.getLatLng();
            const found = allPlaces.find(p => {
              const lat = parseFloat(p.Latitude);
              const lon = parseFloat(p.Longitude);
              if (isNaN(lat) || isNaN(lon)) return false;
              if (Math.abs(lat - pos.lat) < 0.0006 && Math.abs(lon - pos.lng) < 0.0006) return true;
              const pslug = (p.slug || '').toString().toLowerCase();
              if (pslug === slug) return true;
              return false;
            });
            if (found) { targetMarker = m; break; }
          }
        }

        if (!targetMarker) {
          // 🧭 Dynamic SEO Meta Update (use the consumed dl variable)
          if (dl && dl.placeSlug) {
            const name = decodeURIComponent(dl.placeSlug.replace(/-/g, ' '));
            const newTitle = `${name} — The P2V`;
            const newDesc = `Explore ${name} and nearby attractions on The P2V travel map.`;

            document.title = newTitle;
            const descTag = document.querySelector('meta[name="description"]');
            if (descTag) descTag.setAttribute('content', newDesc);

            const ogTitle = document.querySelector('meta[property="og:title"]');
            const ogDesc = document.querySelector('meta[property="og:description"]');
            const twTitle = document.querySelector('meta[name="twitter:title"]');
            const twDesc = document.querySelector('meta[name="twitter:description"]');

            if (ogTitle) ogTitle.setAttribute('content', newTitle);
            if (ogDesc) ogDesc.setAttribute('content', newDesc);
            if (twTitle) twTitle.setAttribute('content', newTitle);
            if (twDesc) twDesc.setAttribute('content', newDesc);

            console.log('🟢 Dynamic meta updated for:', name);
          }

          console.log("Deep-link: no matching marker found. markers:", markers.length);

          // Log analytics (no match)
          try {
            gtag('event', 'deep_link_opened', {
              event_category: 'engagement',
              event_label: dl.placeSlug || (dl.type === 'coords' ? `${dl.lat},${dl.lon}` : 'unknown'),
              value: 0
            });
          } catch (e) {}

          // allow locateUser to resume soon
          P2VState.setSkipAutoFollow(800);
        } else {
          const latlng = targetMarker.getLatLng();
          console.log("Deep-link: matched marker at", latlng);

          // Rough center first
          map.setView(latlng, Math.max(map.getZoom(), 14), { animate: true });

          // Open marker popup (most reliable)
          try {
            targetMarker.openPopup();
          } catch (e) {
            console.warn("marker.openPopup fallback failed", e);
          }

          // Log analytics (success)
          try {
            gtag('event', 'deep_link_opened', {
              event_category: 'engagement',
              event_label: dl.placeSlug || (dl.type === 'coords' ? `${dl.lat},${dl.lon}` : 'unknown'),
              value: 1
            });
          } catch (e) {}

          // small adjust to ensure popup fully within view
          setTimeout(() => {
            try {
              const popupEl = document.querySelector('.leaflet-popup') || document.querySelector('.custom-popup');
              if (popupEl && map) {
                const MAP_MARGIN = 12;
                const popupRect = popupEl.getBoundingClientRect();
                const popupHeight = popupRect.height;
                const popupWidth = popupRect.width;
                const mapSize = map.getSize();
                const containerPoint = map.latLngToContainerPoint(latlng);

                const desiredY = (popupHeight / 2) + MAP_MARGIN;
                if (containerPoint.y < desiredY + 8) {
                  const panByY = desiredY - containerPoint.y;
                  map.panBy([0, -panByY], { animate: true, duration: 0.25 });
                } else {
                  const popupTopInContainer = containerPoint.y - popupHeight - 10;
                  if (popupTopInContainer < MAP_MARGIN) {
                    const panByY = MAP_MARGIN - popupTopInContainer;
                    map.panBy([0, -panByY], { animate: true, duration: 0.25 });
                  }
                }

                // horizontal safe-guard
                const containerX = containerPoint.x;
                if (containerX < (popupWidth / 2) + MAP_MARGIN) {
                  map.panBy([(popupWidth / 2 + MAP_MARGIN) - containerX, 0], { animate: true, duration: 0.25 });
                } else if (containerX > mapSize.x - (popupWidth / 2) - MAP_MARGIN) {
                  map.panBy([mapSize.x - (popupWidth / 2) - MAP_MARGIN - containerX, 0], { animate: true, duration: 0.25 });
                }
              }
            } catch (adjErr) {
              console.warn("Deep-link popup adjust failed:", adjErr);
            } finally {
              // allow locateUser to resume after adjustment
              P2VState.setSkipAutoFollow(600);
            }
          }, 250);
        }
      } catch (err) {
        console.warn("Deep-link handler error:", err);
        pendingDeepLink = null;
        P2VState.setSkipAutoFollow(800);
      } finally {
        // allow locateUser to resume after small delay and reset flag
        setTimeout(() => {
          deepLinkHandled = false;
          P2VState.clearSkipAutoFollow();
        }, 800);
      }
    }


      console.log(`✅ Displayed ${list.length} places.`);
      document.getElementById("loading-overlay").style.display = "none";

    } catch (err) {
      console.error("applyFilters error", err);
    }
  }

  // 🧩 Initialize Firebase (No import version, using compat SDK)
  const firebaseConfig = {
    apiKey: "AIzaSyD7_JcaiWu0nOTSwIwPkPaoYprh_YNXryc",
    authDomain: "ptv-data-25e29.firebaseapp.com",
    projectId: "ptv-data-25e29",
    storageBucket: "ptv-data-25e29.firebasestorage.app",
    messagingSenderId: "955391224203",
    appId: "1:955391224203:web:4b62267d8404647a90678e",
    measurementId: "G-YE5X3MP1PN"
  };

  // ✅ Initialize Firebase
  firebase.initializeApp(firebaseConfig);
  const db = firebase.firestore();

  // 🗺️ Fetch data from Firestore
  async function loadData() {
    try {
      const snapshot = await db.collection("places").get();
      allPlaces = snapshot.docs.map(doc => doc.data());
      console.log(`✅ Data fetched from Firebase: ${allPlaces.length}`);
      restoreFilters();
      locateUser();
    } catch (err) {
      console.error("⚠️ Firebase fetch failed:", err);
      locateUser();
    }
  }

  loadData();




 // 🧭 Locate & Filter buttons
  if (locateBtn) locateBtn.classList.toggle('active', autoFollow); {
    locateBtn.addEventListener("click", () => {
      autoFollow = !autoFollow; // toggle
      localStorage.setItem('ptv_autoFollow', autoFollow ? 'true' : 'false');
      locateBtn.classList.toggle("active", autoFollow);

      if (autoFollow && userLat && userLon) {
        map.flyTo([userLat, userLon], 12, { animate: true });
      }

      // Define message and log it
      const msg = autoFollow
        ? "🟢 Auto-follow ON (map will follow your location)"
        : "🔴 Auto-follow OFF (you can freely explore)";
      console.log(msg);

      // 🧾 Show toast visually
      const msgBox = document.createElement("div");
      msgBox.id = "toast";
      msgBox.textContent = msg;
      document.body.appendChild(msgBox);
      setTimeout(() => msgBox.remove(), 2000);
    });
  }

  


  filterOverlay?.addEventListener("click", () => {
    filterBar.classList.remove("show");
    filterOverlay.style.display = "none";
  });

  // 🎛️ Filter toggle button (to open the filter bar)
  if (filterToggle) {
    filterToggle.addEventListener("click", () => {
      filterBar.classList.toggle("show");
      const isVisible = filterBar.classList.contains("show");
      filterOverlay.style.display = isVisible ? "block" : "none";
    });
}


  // 🧩 Filter & Reset Controls
  document.querySelectorAll(".pop-check")?.forEach(cb =>
    cb.addEventListener("change", applyFilters)
  );

  const distanceFilter = document.getElementById("distanceFilter");
  const statusFilter = document.getElementById("statusFilter");
  const resetBtn = document.getElementById("reset-filters");

  distanceFilter?.addEventListener("change", () => {
    applyFilters();
    gtag('event', 'filter_distance', {
      event_category: 'filter',
      event_label: distanceFilter.value
    });
  });

  statusFilter?.addEventListener("change", () => {
    applyFilters();
    gtag('event', 'filter_status', {
      event_category: 'filter',
      event_label: statusFilter.value
    });
  });


  // 🔄 Reset filters
  resetBtn?.addEventListener("click", () => {
    // Reset popularity checkboxes
    document.querySelectorAll(".pop-check").forEach(cb => (cb.checked = true));

    // Reset dropdowns
    if (distanceFilter) distanceFilter.value = "25";
    if (statusFilter) statusFilter.value = "All";

    // Clear stored filters
    localStorage.removeItem("userFilters");

    // Apply defaults again
    applyFilters();
  });



  // ✅ Register Service Worker (for offline access + updates)
  if ("serviceWorker" in navigator) {
    navigator.serviceWorker
      .register("./service-worker.js")
      .then(reg => console.log("✅ Service Worker registered:", reg.scope))
      .catch(err => console.error("❌ SW registration failed:", err));

    // Optional: listen for version updates
    navigator.serviceWorker.addEventListener("message", event => {
      if (event.data && event.data.type === "NEW_VERSION_AVAILABLE") {
        const toast = document.getElementById("update-toast");
        if (toast) toast.classList.add("show");

        const refreshBtn = document.getElementById("refresh-app");
        if (refreshBtn) {
          refreshBtn.addEventListener("click", () => {
            navigator.serviceWorker.getRegistrations().then(regs => {
              for (const r of regs) r.update();
            });
            window.location.reload(true);
          });
        }
      }
    });
  }




  // 🕒 Guaranteed Splash Removal
  window.addEventListener("load", () => {
    setTimeout(() => {
      const splash = document.getElementById("splash-screen");
      if (splash) {
        splash.classList.add("fade-out");
        setTimeout(() => splash.style.display = "none", 800);
      }
    }, 2500);
  });


  // 🧭 Global function for map direction button
  window.openDirections = function (lat, lon, name) {
    try {
      gtag('event', 'get_directions', {
        event_category: 'engagement',
        event_label: name,
        user_lat: userLat || null,
        user_lon: userLon || null,
        value: 1
      });
    } catch(e){}

    updateEngagementScore(3);

    const confirmMsg = `Do you want to open directions to "${name}" in Google Maps?`;
    if (confirm(confirmMsg)) {
      const mapsUrl = `https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}`;
      window.open(mapsUrl, "_blank", "noopener,noreferrer");
    }
  };



  // 💬 Feedback Modal Logic (resilient version)
  function initFeedbackModal() {
    const feedbackBtn = document.getElementById("feedback-btn");
    const feedbackModal = document.getElementById("feedback-modal");
    const cancelBtn = document.getElementById("cancel-feedback");
    const submitBtn = document.getElementById("submit-feedback");
    const feedbackText = document.getElementById("feedback-text");

    if (!feedbackBtn || !feedbackModal) {
      console.warn("⚠️ Feedback modal elements not ready yet. Retrying...");
      setTimeout(initFeedbackModal, 800);
      return;
    }

    feedbackBtn.addEventListener("click", () => {
      feedbackModal.classList.add("show");
      feedbackText?.focus();
    });

    cancelBtn?.addEventListener("click", () => feedbackModal.classList.remove("show"));

    submitBtn?.addEventListener("click", async () => {
      const text = feedbackText?.value?.trim();
      if (!text) {
        alert("Please write something before sending feedback.");
        return;
      }

      submitBtn.disabled = true;
      submitBtn.textContent = "⏳ Sending...";
      submitBtn.style.opacity = "0.6";

      const data = {
        message: text,
        timestamp: new Date().toLocaleString(),
        userLocation: { lat: userLat || null, lon: userLon || null }
      };

      try {
        await fetch("https://script.google.com/macros/s/AKfycbzqmvWJUOGbFtO02ddkRr3e5_hgn-QmgqnY2ycPyIbxwmuHP9gmBDfD9nK3XDa5diIw3A/exec", {
          method: "POST",
          mode: "no-cors",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(data)
        });
        alert("✅ Thank you for your feedback!");
        feedbackText.value = "";
        feedbackModal.classList.remove("show");
      } catch (err) {
        console.error("Feedback submission failed:", err);
        alert("⚠️ Unable to send feedback. Try again later.");
      } finally {
        setTimeout(() => {
          submitBtn.disabled = false;
          submitBtn.textContent = "Send";
          submitBtn.style.opacity = "1";
        }, 2000);
      }
    });
  }

  window.addEventListener("load", initFeedbackModal);
});





// About modal: robust wiring for both close buttons
(function wireAboutModal() {
  // run after DOM ready (safe if script already inside DOMContentLoaded)
  function init() {
    const infoBtn = document.getElementById("info-btn");
    const aboutModal = document.getElementById("about-modal");
    const closeBtn = document.getElementById("close-Btn");
    const closeAboutTop = document.getElementById("close-about-top");

    if (!aboutModal) {
      console.warn("About modal element not found (#about-modal).");
      return;
    }

    function updateEngagementScore(points) {
      gtag("event", "engagement_score_update", {
        event_category: "score",
        value: points
      });
    }


    // open
    if (infoBtn) {
      infoBtn.addEventListener("click", () => {
        aboutModal.classList.add("show");
        aboutModal.setAttribute("aria-hidden", "false");
      });
    }

    // close handlers
    const closeHandler = () => {

      // optional: return focus to Info button for good UX
      document.getElementById("info-btn")?.focus();

      aboutModal.classList.remove("show");
      aboutModal.setAttribute("aria-hidden", "true");
    };


    if (closeAboutTop) closeAboutTop.addEventListener("click", closeHandler);
    if (closeBtn) closeBtn.addEventListener("click", closeHandler);
    

    // close when clicking outside content
    aboutModal.addEventListener("click", (e) => {
      if (e.target === aboutModal) closeHandler();
    });

    // allow ESC to close
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && aboutModal.classList.contains("show")) closeHandler();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

